<script setup lang="ts">
import { ref } from 'vue'
import type { RegistryAction, RegistryEntry } from '~/types/registry'
import { registryStatus } from '~/utils/registry'
import { moderationLabel } from '~/utils/generation'
defineProps<{entry:RegistryEntry;mutations?:boolean;busy?:boolean}>()
defineEmits<{action:[entry:RegistryEntry,action:RegistryAction]}>()
const menu=ref(false)
function date(v:string|null){return v?new Date(v).toLocaleString('ru-RU',{dateStyle:'medium',timeStyle:'short'}):'Не указано'}
</script>
<template><article class="registry-card" :class="{'registry-card--review':!entry.is_archived&&!['verification_passed','verification_passed_with_warnings'].includes(entry.moderation_status)}"><div class="registry-card-top"><UiBadge :tone="entry.is_archived?'neutral':entry.status==='completed'?'success':'warning'">{{ registryStatus(entry) }}</UiBadge><details :open="menu" class="registry-menu" @keydown.esc.prevent="menu=false" @toggle="menu=($event.target as HTMLDetailsElement).open"><summary :aria-label="`Действия: ${entry.title}`"><img src="/icons/fe009/ellipsis.svg" width="18" height="18" alt=""></summary><nav :aria-label="`Меню сценария ${entry.title}`"><NuxtLink :to="`/scenarios/${entry.id}`">Просмотреть сценарий</NuxtLink><NuxtLink :to="`/scenarios/${entry.id}/edit`">Редактор и проверка</NuxtLink><NuxtLink :to="`/scenarios/${entry.id}?export=1`">Экспорт и история</NuxtLink><template v-if="mutations"><button v-if="!entry.is_archived" :disabled="busy" @click="menu=false;$emit('action',entry,'archive')">Архивировать</button><button v-else :disabled="busy" @click="menu=false;$emit('action',entry,'restore')">Восстановить</button><button class="registry-delete" :disabled="busy" @click="menu=false;$emit('action',entry,'delete')">Удалить сценарий</button></template></nav></details></div><p class="registry-version">{{ entry.current_revision?`Текущая версия ${entry.current_revision.version_number}`:'Номер текущей версии не передан' }}</p><h2><NuxtLink :to="`/scenarios/${entry.id}`">{{ entry.title }}</NuxtLink></h2><dl><div><dt>Создан</dt><dd>{{ date(entry.created_at) }}</dd></div><div><dt>Изменён</dt><dd>{{ date(entry.updated_at) }}</dd></div></dl><p class="registry-moderation">{{ moderationLabel(entry.moderation_status) }}</p><p v-if="entry.status==='completed'" class="registry-note">Наличие записи подтверждения не доказывает актуальность источников и допуска.</p><p v-else-if="entry.is_archived" class="registry-note">Архив сохраняет сценарий. Допуск к документам проверяется отдельно.</p><p v-else class="registry-note">Проект требует проверки педагогом. Удаление может быть запрещено подтверждением другой ревизии.</p><div class="registry-card-links"><NuxtLink :to="`/scenarios/${entry.id}`">Открыть →</NuxtLink><NuxtLink :to="`/scenarios/${entry.id}/edit`">Редактор</NuxtLink><NuxtLink :to="`/scenarios/${entry.id}?export=1`">Экспорт и история</NuxtLink></div></article></template>
